        "react": "function Grid({ cards }) {\n  return (\n    <div>\n      <p id=\"count\">{cards.length} cards</p>\n      <div id=\"grid\">\n        {cards.map((item) => (\n          <article key={item.id} className=\"card\">{item.title}</article>\n        ))}\n      </div>\n    </div>\n  );\n}"
